% Observable: We can figure out all internal states just by watching the output.


%% Observability check

O = obsv(A, C);        % Observability matrix
rankO = rank(O);       % Rank of observability matrix
n = size(A,1);         % System order

disp('Observability matrix O = ');disp(O); %[output:50e3d0f5]
disp(['rank(O) = ' num2str(rankO) ', n = ' num2str(n)]); %[output:7ee67bc5]

if rankO == n %[output:group:060de39b]
    disp('The realization IS observable.'); %[output:4f5e5090]
else
    disp('The realization is NOT observable.');
end %[output:group:060de39b]

